import{_ as t,o as a,c as o,a3 as s}from"./chunks/framework.BNNhFWPR.js";const u=JSON.parse('{"title":"Projects and files","description":"Where projects are stored on your computer and how to reach their files with project:// paths.","frontmatter":{"id":"projects","title":"Projects and files","order":2,"description":"Where projects are stored on your computer and how to reach their files with project:// paths.","editUrl":"https://github.com/ATMO-Engine/atmo/edit/main/docs/en/getting-started/projects.md"},"headers":[],"relativePath":"getting-started/projects.md","filePath":"en/getting-started/projects.md"}'),r={name:"getting-started/projects.md"};function i(n,e,d,h,c,p){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="projects-and-files" tabindex="-1">Projects and files <a class="header-anchor" href="#projects-and-files" aria-label="Permalink to &quot;Projects and files&quot;">​</a></h1><h2 id="location" tabindex="-1">Where projects are stored <a class="header-anchor" href="#location" aria-label="Permalink to &quot;Where projects are stored {#location}&quot;">​</a></h2><p>Projects created from the project list, the window that opens when the engine starts without <code>--project</code>, are stored in the <code>projects</code> folder of the engine&#39;s user data directory:</p><table tabindex="0"><thead><tr><th>Platform</th><th>Location</th></tr></thead><tbody><tr><td>Windows</td><td><code>%APPDATA%\\atmo\\userdata\\projects\\&lt;name&gt;</code></td></tr><tr><td>macOS</td><td><code>~/Library/Application Support/atmo/userdata/projects/&lt;name&gt;</code></td></tr><tr><td>Linux</td><td><code>~/.local/share/atmo/userdata/projects/&lt;name&gt;</code></td></tr></tbody></table><p><code>&lt;name&gt;</code> is the name typed when creating the project. The project list shows every project found there, with its full path.</p><p>A project can also live anywhere else on the disk. It is then not in the list, and is opened by its path:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">atmo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/my-game</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # open in the editor</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">atmo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/my-game</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # run the game without the editor</span></span></code></pre></div><p>To move a project, move its whole folder: paths written with <a href="#project-paths"><code>project://</code></a> keep working.</p><h2 id="layout" tabindex="-1">What a project contains <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;What a project contains {#layout}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-game/</span></span>
<span class="line"><span>├── .atmo/</span></span>
<span class="line"><span>│   └── project_settings.json</span></span>
<span class="line"><span>└── assets/</span></span>
<span class="line"><span>    └── atmo.png</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Path</th><th>Contents</th></tr></thead><tbody><tr><td><code>.atmo/project_settings.json</code></td><td>The project settings. A folder is a project when it contains this file.</td></tr><tr><td><code>assets/atmo.png</code></td><td>The default project icon.</td></tr></tbody></table><p>These are the only files the engine creates. Everything else is up to you: scenes, scripts, images and materials can be in any folder of the project. The examples in this documentation use <code>assets/script/</code> for scripts and <code>assets/prefabs/</code> for prefabs.</p><h2 id="project-paths" tabindex="-1">Reaching files with project:// <a class="header-anchor" href="#project-paths" aria-label="Permalink to &quot;Reaching files with project:// {#project-paths}&quot;">​</a></h2><p><code>project://</code> stands for the project&#39;s root folder. What follows is the path of the file inside the project, with <code>/</code> as the separator on every platform. In a project stored in <code>~/.local/share/atmo/userdata/projects/my-game</code>:</p><table tabindex="0"><thead><tr><th>Path</th><th>File</th></tr></thead><tbody><tr><td><code>project://main.ascn</code></td><td><code>~/.local/share/atmo/userdata/projects/my-game/main.ascn</code></td></tr><tr><td><code>project://assets/script/player.luau</code></td><td><code>~/.local/share/atmo/userdata/projects/my-game/assets/script/player.luau</code></td></tr></tbody></table><p>Write two slashes: <code>project:/main.ascn</code> is not recognized, and is looked up as an ordinary path on the disk.</p><p><code>project://</code> paths work wherever the engine loads a file:</p><ul><li>in the editor, in path fields such as <code>script_path</code>, <code>texture_path</code> or <code>material_path</code>;</li><li>in the project settings, for example in <code>default_scene</code>;</li><li>in scripts, in the functions that take a path: see <a href="/latest/manual/luau-api#prefab" class="atmo-ref atmo-ref--page" data-preview="Every engine type and function available to Luau scripts.">Prefab</a>, <a href="/latest/manual/luau-api#sprite2d" class="atmo-ref atmo-ref--page" data-preview="Every engine type and function available to Luau scripts.">Sprite2d</a> and <a href="/latest/manual/luau-api#material" class="atmo-ref atmo-ref--page" data-preview="Every engine type and function available to Luau scripts.">Material</a>.</li></ul><p>Scripts have no function to read, write or list files themselves.</p><h3 id="other-paths" tabindex="-1">Why not another path <a class="header-anchor" href="#other-paths" aria-label="Permalink to &quot;Why not another path {#other-paths}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Path</th><th>What happens</th></tr></thead><tbody><tr><td><code>project://assets/hero.png</code></td><td>Works in the editor, in run mode, in exported games and on other computers.</td></tr><tr><td><code>/home/me/my-game/hero.png</code></td><td>Only works on this computer.</td></tr><tr><td><code>assets/hero.png</code></td><td>Relative to the directory the engine was started from, which may not be the project.</td></tr></tbody></table><h3 id="lookup" tabindex="-1">Where project:// looks <a class="header-anchor" href="#lookup" aria-label="Permalink to &quot;Where project:// looks {#lookup}&quot;">​</a></h3><p>In the editor and in run mode, the engine looks for the file:</p><ol><li>in the project folder;</li><li>in the files packed inside the engine itself, such as its fonts and icons.</li></ol><p>This is why <code>project://assets/fonts/Nunito/Nunito.ttf</code> works in a project that has no fonts. It also means that a file of the project hides an engine file with the same path.</p><p>An exported game contains the whole project folder, and <code>project://</code> reads from inside the executable. These files are read-only. The engine&#39;s own files are not looked up there: copy the ones your game uses into the project before exporting.</p><h3 id="not-found" tabindex="-1">File not found <a class="header-anchor" href="#not-found" aria-label="Permalink to &quot;File not found {#not-found}&quot;">​</a></h3><p><code>File not found in packed file system: &quot;assets/hero.png&quot;</code> means that the file was found neither in the project nor in the engine. Check the spelling, including upper and lower case, which matters on Linux.</p><h2 id="user-paths" tabindex="-1">user:// paths <a class="header-anchor" href="#user-paths" aria-label="Permalink to &quot;user:// paths {#user-paths}&quot;">​</a></h2><p><code>user://</code> stands for the user data directory, outside of the project:</p><table tabindex="0"><thead><tr><th>Platform</th><th>Editor and run mode</th><th>Exported game</th></tr></thead><tbody><tr><td>Windows</td><td><code>%APPDATA%\\atmo\\userdata</code></td><td><code>%APPDATA%\\&lt;project_name&gt;</code></td></tr><tr><td>macOS</td><td><code>~/Library/Application Support/atmo/userdata</code></td><td><code>~/Library/Application Support/&lt;project_name&gt;</code></td></tr><tr><td>Linux</td><td><code>~/.local/share/atmo/userdata</code></td><td><code>~/.local/share/&lt;project_name&gt;</code></td></tr></tbody></table><p><code>&lt;project_name&gt;</code> is the name in the project settings. Game assets belong in the project, with <code>project://</code>: what is in <code>user://</code> is not exported.</p><h2 id="default-scene" tabindex="-1">The scene the game starts with <a class="header-anchor" href="#default-scene" aria-label="Permalink to &quot;The scene the game starts with {#default-scene}&quot;">​</a></h2><p>Set <code>default_scene</code> in the project settings to the <code>.ascn</code> file of the first scene, for example <code>project://main.ascn</code>. The Play button, <code>--run</code> and exported games load it. <code>--run</code> can also be given another scene:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">atmo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/my-game</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> project://levels/level_2.ascn</span></span></code></pre></div><p>The scripts attached to the entities of that scene are what runs first: continue with <a href="/latest/manual/scripting" class="atmo-ref atmo-ref--page" data-preview="Attach Luau scripts to entities and use the functions the engine calls.">Scripting</a>.</p>`,36)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
